<#
Codex OpenCode Go Setup -- configuration manager (Windows)

Run:  irm https://github.com/tangzihui/opencode-go-setup/raw/main/Codex-opencodego-setup.ps1 | iex

After launch, pick a menu item:
  1 = use deepseek-v4-flash    2 = use deepseek-v4-pro    3 = restore default config

Generated by build.py -- do not edit directly (edit template-intl.ps1 and rebuild).
#>

# Note: this script is usually executed via irm | iex inside the user's current
# session, where exit would close the user's terminal window. All aborts therefore
# go through Die -> throw sentinel, swallowed by the dispatcher's try/catch at the
# bottom; ErrorActionPreference / StrictMode are only set inside entry functions
# to avoid polluting the session.

$SCRIPT_VERSION   = '1.0.0'
$FLASH_SLUG       = 'deepseek-v4-flash'
$PRO_SLUG         = 'deepseek-v4-pro'
$PROVIDER_ID      = 'opencode-go'
$DEFAULT_BASE_URL = 'https://opencode.ai/zen/go/v1'
$BACKUP_DIRNAME   = 'backup-opencode-go'

$SCRIPT_URL  = 'https://github.com/tangzihui/opencode-go-setup/raw/main/Codex-opencodego-setup.ps1'
$INSTALL_CMD = "irm $SCRIPT_URL | iex"

$ABORT_SENTINEL = '__OPENCODE_GO_CODEX_SETUP_ABORT__'

$script:ModelSlug = ''   # decided by the menu choice

# ---------------------------------------------------------------- output helpers

function Write-Ok    { param($m) Write-Host "[OK] " -ForegroundColor Green -NoNewline; Write-Host $m }
function Write-Warn2 { param($m) Write-Host "[!]  " -ForegroundColor Yellow -NoNewline; Write-Host $m }
function Write-Head  { param($m) Write-Host ''; Write-Host $m -ForegroundColor White }
function Write-Dim   { param($m) Write-Host $m -ForegroundColor DarkGray }
function Die {
    param($m)
    Write-Host ''
    Write-Host "[X] $m" -ForegroundColor Red
    throw $ABORT_SENTINEL
}

# ---------------------------------------------------------------- paths

$CodexHomeDir = if ($env:CODEX_HOME) { $env:CODEX_HOME } else { Join-Path $HOME '.codex' }
$ConfigPath   = Join-Path $CodexHomeDir 'config.toml'
$ModelsPath   = Join-Path $CodexHomeDir 'models.json'
$BackupDir    = Join-Path $CodexHomeDir $BACKUP_DIRNAME
$BackupConfig = Join-Path $BackupDir 'config.toml'
$BackupModels = Join-Path $BackupDir 'models.json'
$Manifest     = Join-Path $BackupDir 'manifest.txt'

# On Windows we cannot confirm Codex expands ~, and when it doesn't the failure is
# silent (fallback metadata). Always write the resolved absolute path with forward
# slashes (backslash is an escape character in TOML).
$CatalogValue = $ModelsPath -replace '\\', '/'

# ---------------------------------------------------------------- restore (menu 3)

function Invoke-OpenCodeGoRestore {
    $ErrorActionPreference = 'Stop'
    Set-StrictMode -Version Latest

    Write-Head 'Restore the default Codex configuration (remove opencode-go settings)'
    if (-not (Test-Path -LiteralPath $BackupDir)) {
        Die "Backup directory not found:`n  $BackupDir`nNothing to restore -- the script may never have been installed, or was already restored."
    }

    $hadConfig = $true
    if (Test-Path -LiteralPath $Manifest) {
        if ((Get-Content -LiteralPath $Manifest -Raw) -match 'original_config_existed=0') {
            $hadConfig = $false
        }
    }
    $hadModels = $false
    if (Test-Path -LiteralPath $Manifest) {
        if ((Get-Content -LiteralPath $Manifest -Raw) -match 'original_models_existed=1') {
            $hadModels = $true
        }
    }

    $n = 1
    Write-Host ''
    Write-Host 'The following actions will be performed:'
    if ($hadConfig) {
        if (-not (Test-Path -LiteralPath $BackupConfig)) {
            Die "Backup is corrupted: missing $BackupConfig"
        }
        Write-Host "  $n. Delete the current $ConfigPath"; $n++
        Write-Host '     (any changes made to this file since installation will be lost)' -ForegroundColor Yellow
        Write-Host "  $n. Restore config.toml from the backup"; $n++
    } else {
        Write-Host "  $n. Delete $ConfigPath"; $n++
        Write-Dim  '     (this file did not exist before installation)'
    }
    if ($hadModels) {
        if (-not (Test-Path -LiteralPath $BackupModels)) {
            Die "Backup is corrupted: missing $BackupModels"
        }
        Write-Host "  $n. Delete the current $ModelsPath"; $n++
        Write-Host "  $n. Restore models.json from the backup"; $n++
    } else {
        Write-Host "  $n. Delete $ModelsPath"; $n++
        Write-Dim  '     (this file did not exist before installation)'
    }
    Write-Host "  $n. Delete the backup directory $BackupDir"
    Write-Host ''

    $ans = Read-Host 'Restore now? Type y to continue, anything else to cancel'
    if ($ans -notin @('y','Y','yes','YES')) {
        Write-Host 'Cancelled; nothing was modified.'
        return
    }

    if ($hadConfig) {
        Copy-Item -LiteralPath $BackupConfig -Destination $ConfigPath -Force
        Write-Ok 'config.toml restored'
    } else {
        if (Test-Path -LiteralPath $ConfigPath) { Remove-Item -LiteralPath $ConfigPath -Force }
        Write-Ok 'config.toml deleted (it did not exist before installation)'
    }
    if (Test-Path -LiteralPath $ModelsPath) { Remove-Item -LiteralPath $ModelsPath -Force }
    if ($hadModels) {
        Copy-Item -LiteralPath $BackupModels -Destination $ModelsPath -Force
        Write-Ok 'models.json restored'
    } else {
        Write-Ok 'models.json deleted (it did not exist before installation)'
    }

    Remove-Item -LiteralPath $BackupDir -Recurse -Force
    Write-Ok 'Backup directory cleaned up'
    Write-Host ''
    Write-Ok 'Restore complete; the Codex configuration is back to its pre-install state.'
    Write-Dim "To install again: $INSTALL_CMD"
}

# ---------------------------------------------------------------- TOML scanner

# Tracks bracket depth and multi-line strings so we can tell which lines are real
# section headers
$script:Depth = 0
$script:MlState = ''

function Update-ScanState {
    param([string]$Line)
    $n = $Line.Length
    $i = 0
    $instr = ''
    while ($i -lt $n) {
        $c = $Line[$i]
        $c3 = if ($i + 3 -le $n) { $Line.Substring($i, 3) } else { '' }

        if ($script:MlState) {
            if ($script:MlState -eq 'basic' -and $c3 -eq '"""') { $script:MlState = ''; $i += 3; continue }
            if ($script:MlState -eq 'literal' -and $c3 -eq "'''") { $script:MlState = ''; $i += 3; continue }
            if ($script:MlState -eq 'basic' -and $c -eq '\') { $i += 2; continue }
            $i++; continue
        }
        if ($instr) {
            if ($instr -eq 'basic') {
                if ($c -eq '\') { $i += 2; continue }
                if ($c -eq '"') { $instr = '' }
            } else {
                if ($c -eq "'") { $instr = '' }
            }
            $i++; continue
        }
        if ($c3 -eq '"""') { $script:MlState = 'basic';   $i += 3; continue }
        if ($c3 -eq "'''") { $script:MlState = 'literal'; $i += 3; continue }

        switch ($c) {
            '#' { return }
            '"' { $instr = 'basic' }
            "'" { $instr = 'literal' }
            '[' { $script:Depth++ }
            ']' { if ($script:Depth -gt 0) { $script:Depth-- } }
        }
        $i++
    }
}

function Get-TomlKey {
    param([string]$Line)
    $l = $Line.Trim()
    if ($l -eq '' -or $l.StartsWith('#')) { return '' }
    $eq = $l.IndexOf('=')
    if ($eq -lt 1) { return '' }
    $k = $l.Substring(0, $eq).Trim()
    return $k.Trim('"').Trim("'")
}

function Get-TomlValue {
    param([string]$Line)
    $l = $Line.Trim()
    $eq = $l.IndexOf('=')
    if ($eq -lt 0) { return '' }
    return $l.Substring($eq + 1).Trim()
}

$TARGET_KEYS = @('model','model_provider','preferred_auth_method','forced_login_method',
                 'model_reasoning_effort','model_catalog_json')

$DEL_A = @{
    'profile'         = 'a profile masks model / model_provider / model_catalog_json, and this version rejects it'
    'oss_provider'    = 'alternate provider selector that would redirect requests elsewhere'
    'openai_base_url' = 'global base_url override that would hijack requests'
}

$DEL_B = [ordered]@{
    'model_context_window'               = 'overrides the 1M context window from models.json; if too large, auto-compaction never triggers and the API errors mid-run'
    'model_auto_compact_token_limit'      = 'overrides when auto-compaction happens'
    'model_auto_compact_token_limit_scope'= 'overrides when auto-compaction happens'
    'base_instructions'                  = 'overrides base_instructions from models.json'
    'model_instructions_file'            = 'overrides base_instructions from models.json'
    'compact_prompt'                     = 'overrides the context-compaction prompt'
    'experimental_compact_prompt_file'   = 'overrides the context-compaction prompt'
    'service_tier'                       = 'a stale value is sent to the API as a parameter and may cause a 400'
    'model_verbosity'                    = 'a stale value may be outside what the model supports'
    'model_reasoning_summary'            = 'models.json declares default_reasoning_summary=none; a stale value would send reasoning.summary'
    'plan_mode_reasoning_effort'         = 'may be xhigh, while models.json only declares low / high / max'
    'experimental_use_unified_exec_tool' = 'conflicts with shell_type=shell_command in models.json'
}

$WARN_KEYS = @('review_model','experimental_thread_config_endpoint',
               'experimental_thread_store_endpoint','experimental_thread_store')

function Get-TargetValue {
    param([string]$Key)
    switch ($Key) {
        'model'                  { return "`"$($script:ModelSlug)`"" }
        'model_provider'         { return "`"$PROVIDER_ID`"" }
        'preferred_auth_method'  { return '"apikey"' }
        'forced_login_method'    { return '"api"' }
        'model_reasoning_effort' { return '"high"' }
        'model_catalog_json'     { return "`"$CatalogValue`"" }
    }
    return '""'
}

function Format-Val {
    param([string]$v)
    if ($v.Length -gt 58) { return $v.Substring(0, 58) + '...' }
    return $v
}

# ---------------------------------------------------------------- case b: switch model only

# Fast path when both the backup and models.json look as expected: replace only the
# top-level model key in config.toml's leading area; leave everything else (base_url,
# API key, previous surgery results) untouched.
function Invoke-OpenCodeGoSwitchModel {
    $ErrorActionPreference = 'Stop'
    Set-StrictMode -Version Latest

    Write-Head "Switching default model -> $($script:ModelSlug)"
    Write-Dim  'Backup and models.json from this script detected; only the model field in config.toml will be updated.'

    $raw = Get-Content -LiteralPath $ConfigPath -Raw -Encoding UTF8
    if ($null -eq $raw) { $raw = '' }
    $raw = $raw -replace "`r`n", "`n"
    $raw = $raw.TrimEnd("`n")
    if ($raw -eq '') { $Lines = @() } else { $Lines = $raw -split "`n" }

    $Out = New-Object System.Collections.Generic.List[string]
    $script:Depth = 0
    $script:MlState = ''
    $i = 0
    $replaced = $false
    $inLeading = $true

    while ($i -lt $Lines.Count) {
        $line = $Lines[$i]
        if (-not $inLeading) {
            $Out.Add($line); $i++; continue
        }
        # Continuation lines of multi-line strings/arrays pass through without key parsing
        if ($script:MlState -or $script:Depth -ne 0) {
            Update-ScanState $line
            $Out.Add($line); $i++; continue
        }
        $trimmed = $line.Trim()
        $isHeader = $trimmed.StartsWith('[')
        if ($isHeader) {
            # Leading area ended without seeing model -> insert before the first section
            if (-not $replaced) {
                $Out.Add("model = `"$($script:ModelSlug)`"")
                $Out.Add('')
                $replaced = $true
            }
            $inLeading = $false
            $Out.Add($line); $i++; continue
        }
        $k = Get-TomlKey $line
        if ($k -eq 'model') {
            # Swallow the complete assignment (could theoretically be a multi-line string)
            Update-ScanState $line
            $i++
            while (($script:MlState -or $script:Depth -ne 0) -and $i -lt $Lines.Count) {
                Update-ScanState $Lines[$i]
                $i++
            }
            $Out.Add("model = `"$($script:ModelSlug)`"")
            $replaced = $true
            continue
        }
        Update-ScanState $line
        $Out.Add($line); $i++
    }
    if (-not $replaced) {
        $Out.Add("model = `"$($script:ModelSlug)`"")
    }

    $TmpConfig = "$ConfigPath.opencodego-tmp"
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($TmpConfig, (($Out -join "`n") + "`n"), $utf8NoBom)
    Move-Item -LiteralPath $TmpConfig -Destination $ConfigPath -Force

    Write-Ok "config.toml updated: model = `"$($script:ModelSlug)`""
    Write-Host ''
    Write-Host 'How to verify it took effect:'
    Write-Host '  - ChatGPT desktop app: after launch, the bottom-right corner showing the DeepSeek model name means success'
    Write-Host "    (that is $($script:ModelSlug); if it still shows `"Custom`", models.json was not loaded)"
    Write-Host "  - Codex CLI: the startup banner shows model: $($script:ModelSlug)"
    Write-Host ''
    Write-Dim 'Run this script again to switch models (pick 1/2) or restore the default config (pick 3).'
}

# ---------------------------------------------------------------- install (case a)

function Invoke-OpenCodeGoInstall {
    $ErrorActionPreference = 'Stop'
    Set-StrictMode -Version Latest

    Write-Head "First-time install (target model: $($script:ModelSlug))"

    # ---- interactive input

    # base_url is fixed to the public API endpoint -- never prompted for,
    # never overridable
    $BaseUrl = $DEFAULT_BASE_URL

    $ApiKey = $env:OPENCODE_API_KEY
    if ($ApiKey) {
        if ($ApiKey -cnotlike 'sk-*') {
            Die 'The OPENCODE_API_KEY environment variable does not start with sk-; please check it and try again (no files were modified).'
        }
        Write-Host ''
        Write-Ok 'Using the API key from the OPENCODE_API_KEY environment variable; skipping the prompt.'
    }

    Write-Host ''
    if (-not $ApiKey) {
        Write-Dim "Don't have an API key yet? Create one at https://opencode.ai/auth"
    }
    $keyAttempt = 0
    while (-not $ApiKey) {
        try {
            $ApiKey = (Read-Host 'Enter your OpenCode Go API key (starts with sk-)').Trim()
        } catch {
            Die 'Cannot read input (non-interactive environment); exiting (no files were modified).'
        }
        if ($ApiKey -cnotlike 'sk-*') {
            $ApiKey = ''
            $keyAttempt++
            if ($keyAttempt -ge 3) {
                Die 'Failed to get a valid API key (it must start with sk-); exiting (no files were modified).'
            }
            Write-Warn2 'The API key must start with sk-.'
        }
    }

    if ($ApiKey -match '"')  { Die 'The API key must not contain double quotes.' }

    # ---- backup

    New-Item -ItemType Directory -Path $BackupDir -Force | Out-Null

    $OrigExisted = Test-Path -LiteralPath $ConfigPath
    if ($OrigExisted) {
        Copy-Item -LiteralPath $ConfigPath -Destination $BackupConfig -Force
        Write-Ok "Backed up config.toml -> $BackupConfig"
    } else {
        Write-Warn2 'config.toml not found; a new file will be created'
    }

    $OrigModelsExisted = Test-Path -LiteralPath $ModelsPath
    if ($OrigModelsExisted) {
        Copy-Item -LiteralPath $ModelsPath -Destination $BackupModels -Force
        Write-Ok "Backed up models.json -> $BackupModels"
        Write-Dim 'The existing models.json already contains the DeepSeek V4 models; it will be replaced after the backup.'
    } else {
        Write-Warn2 'models.json not found; a new file will be created'
    }

    # ---- processing

    $Lines = @()
    if ($OrigExisted) {
        $raw = Get-Content -LiteralPath $ConfigPath -Raw -Encoding UTF8
        if ($null -eq $raw) { $raw = '' }
        # -split on an empty string yields one empty element, so check for '' first
        $raw = $raw -replace "`r`n", "`n"
        $raw = $raw.TrimEnd("`n")
        if ($raw -eq '') { $Lines = @() } else { $Lines = $raw -split "`n" }
    }

    $Out    = New-Object System.Collections.Generic.List[string]
    $Report = New-Object System.Collections.Generic.List[string]
    $Seen   = New-Object System.Collections.Generic.HashSet[string]
    $InsAt  = 0

    $script:Depth = 0
    $script:MlState = ''
    $script:idx = 0
    $curSection = ''
    $skipSection = $false

    # Swallow one complete assignment (including multi-line arrays / strings);
    # $Lines is visible via the caller's scope
    function Consume-Block {
        while ($script:idx -lt $Lines.Count) {
            Update-ScanState $Lines[$script:idx]
            $script:idx++
            if (-not $script:MlState -and $script:Depth -eq 0) { break }
        }
    }

    while ($script:idx -lt $Lines.Count) {
        $line = $Lines[$script:idx]
        $trimmed = $line.Trim()

        $isHeader = (-not $script:MlState) -and ($script:Depth -eq 0) -and $trimmed.StartsWith('[')

        if ($isHeader) {
            $hdr = $trimmed
            $close = $hdr.IndexOf(']')
            if ($close -gt 0) { $hdr = $hdr.Substring(0, $close + 1) }
            $hdr = $hdr.TrimStart('[').TrimEnd(']').Trim().Replace('"','').Replace("'",'')
            $curSection = $hdr
            $skipSection = $false

            if ($hdr -eq "model_providers.$PROVIDER_ID" -or $hdr -like "model_providers.$PROVIDER_ID.*") {
                $skipSection = $true
                $Report.Add("Removed the old [$hdr] (it will be rewritten with the new settings)")
            }
            elseif ($hdr -eq 'profiles' -or $hdr -like 'profiles.*') {
                $skipSection = $true
                $Report.Add("Removed [$hdr]  <- a profile masks model / model_provider etc., and this version rejects it")
            }
            elseif ($hdr -eq 'auto_review') {
                $Report.Add("Kept [$hdr]  (note: if auto_review points at a gpt-5.x model it will use fallback metadata)")
            }
            elseif ($hdr -eq 'tui.model_availability_nux') {
                $Report.Add("Kept [$hdr]  (NUX counters only, harmless)")
            }

            Update-ScanState $line
            $script:idx++
            if (-not $skipSection) { $Out.Add($line) }
            continue
        }

        if ($curSection) {
            if ($skipSection) { Update-ScanState $line; $script:idx++; continue }

            if ((Get-TomlKey $line) -eq 'wire_api') {
                $v = Get-TomlValue $trimmed
                if ($v -match '^["'']chat["'']') {
                    $indent = $line.Substring(0, $line.Length - $line.TrimStart().Length)
                    $Out.Add("${indent}wire_api = `"responses`"")
                    $Report.Add("Fixed wire_api in [$curSection]: `"chat`" -> `"responses`"  <- `"chat`" prevents Codex from starting in this version")
                    Update-ScanState $line
                    $script:idx++
                    continue
                }
            }
            $Out.Add($line)
            Update-ScanState $line
            $script:idx++
            continue
        }

        # ---- leading area (top-level keys)
        $k = Get-TomlKey $line

        if ($k -and $TARGET_KEYS -contains $k) {
            $oldv = Get-TomlValue $trimmed
            $newv = Get-TargetValue $k
            Consume-Block
            $Out.Add("$k = $newv")
            $InsAt = $Out.Count
            [void]$Seen.Add($k)
            if ($oldv -ne $newv) {
                $Report.Add("Rewrote $k`: $(Format-Val $oldv) -> $newv")
            }
            continue
        }

        if ($k -and $DEL_A.Contains($k)) {
            $oldv = Get-TomlValue $trimmed
            Consume-Block
            $Report.Add("Removed $k = $(Format-Val $oldv)  <- $($DEL_A[$k])")
            continue
        }

        if ($k -and $DEL_B.Contains($k)) {
            $oldv = Get-TomlValue $trimmed
            Consume-Block
            $Report.Add("Removed $k = $(Format-Val $oldv)  <- $($DEL_B[$k])")
            continue
        }

        if ($k -and $WARN_KEYS -contains $k) {
            $Report.Add("Kept $k  (note: may cause fallback metadata or be overridden by remote config)")
        }

        $Out.Add($line)
        if ($k) { $InsAt = $Out.Count }
        Update-ScanState $line
        $script:idx++
    }

    $missing = @($TARGET_KEYS | Where-Object { -not $Seen.Contains($_) })

    # ---- assembly

    $final = New-Object System.Collections.Generic.List[string]
    for ($i = 0; $i -lt $Out.Count; $i++) {
        if ($i -eq $InsAt -and $missing.Count -gt 0) {
            foreach ($k in $missing) { $final.Add("$k = $(Get-TargetValue $k)") }
            $missing = @()
            # Insert a blank line when adjacent to a section header so the keys
            # don't visually appear to belong to that section
            if ($Out[$i].Trim().StartsWith('[')) { $final.Add('') }
        }
        $final.Add($Out[$i])
    }
    foreach ($k in $missing) { $final.Add("$k = $(Get-TargetValue $k)") }

    $final.Add('')
    $final.Add("[model_providers.$PROVIDER_ID]")
    $final.Add("name = `"$PROVIDER_ID`"")
    $final.Add("base_url = `"$BaseUrl`"")
    $final.Add('wire_api = "responses"')
    $final.Add("experimental_bearer_token = `"$ApiKey`"")

    $TmpConfig = "$ConfigPath.opencodego-tmp"
    $TmpModels = "$ModelsPath.opencodego-tmp"

    # Codex reads UTF-8; UTF8Encoding($false) avoids the BOM on PS 5.1
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($TmpConfig, (($final -join "`n") + "`n"), $utf8NoBom)

    $ModelsJson = @'
{
  "models": [
    {
      "slug": "deepseek-v4-flash",
      "prefer_websockets": false,
      "support_verbosity": true,
      "default_verbosity": "low",
      "apply_patch_tool_type": "freeform",
      "web_search_tool_type": "text",
      "input_modalities": [
        "text"
      ],
      "supports_image_detail_original": false,
      "truncation_policy": {
        "mode": "tokens",
        "limit": 10000
      },
      "supports_parallel_tool_calls": true,
      "tool_mode": null,
      "multi_agent_version": "v2",
      "use_responses_lite": false,
      "include_skills_usage_instructions": false,
      "auto_review_model_override": null,
      "context_window": 1048576,
      "max_context_window": 1048576,
      "effective_context_window_percent": 95,
      "auto_compact_token_limit": null,
      "comp_hash": "3000",
      "reasoning_summary_format": "experimental",
      "default_reasoning_summary": "none",
      "display_name": "DeepSeek-V4-Flash",
      "description": "Latest frontier agentic coding model.",
      "default_reasoning_level": "high",
      "supported_reasoning_levels": [
        {
          "effort": "low",
          "description": "Fast responses with lighter reasoning"
        },
        {
          "effort": "high",
          "description": "Extra high reasoning depth for complex problems"
        },
        {
          "effort": "max",
          "description": "Maximum reasoning depth for the hardest problems"
        }
      ],
      "shell_type": "shell_command",
      "visibility": "list",
      "minimal_client_version": "0.144.0",
      "supported_in_api": true,
      "availability_nux": null,
      "upgrade": null,
      "priority": 1,
